document.getElementById('signupForm').addEventListener('submit', event => {
  const email = document.getElementById('email').value.trim();
  const age = Number(document.getElementById('age').value);
  const error = document.getElementById('error');
  if (email === '' || !Number.isInteger(age) || age < 18 || age > 60) {
    event.preventDefault();
    error.textContent = 'Enter an email and an age from 18 to 60.';
  } else {
    error.textContent = '';
  }
});

function calculateAverage(a, b, c) {
  return (a + b + c) / 3;
}
const average = calculateAverage(60, 45, 75);
const category = average >= 50 ? 'PASS' : 'FAIL';
document.getElementById('result').textContent =
  `Average: ${average.toFixed(2)} - ${category}`;

